-- BM Apple Iphone Store Stock - Full Import
-- Source: BM Apple Iphone Store Stock.xlsx
-- Total items: 252
-- Store: BM Apple Iphone Store (a0000000-0000-0000-0000-000000000001)
-- Run this in Supabase SQL Editor
-- ============================================

-- 1. Clear old stock for this store only
DELETE FROM public.stock WHERE store_id = 'a0000000-0000-0000-0000-000000000001';
DELETE FROM public.stock_lots WHERE store_id = 'a0000000-0000-0000-0000-000000000001';

-- 2. Insert stock items

-- 3. Insert stock lots (one lot per item for FIFO sales)

-- 4. Reset sequences (global — set to max across ALL stores)
SELECT setval('public.stock_code_seq', GREATEST(1, (SELECT COALESCE(MAX(CAST(code AS integer)), 0) FROM public.stock)));
SELECT setval('public.lot_no_seq', GREATEST(1, (SELECT COALESCE(MAX(CAST(SUBSTRING(lot_no FROM 5) AS integer)), 0) FROM public.stock_lots)));
